"C:\\WINDOWS\\System32\\WindowsPowerShell\\v1.0\\powershell.exe" -Command '# Find ALL manifest_id lines in exec_roster.json and get their context
$lines = Get-Content "E:'"\\codex-LOOP\\codex-loop-s-f2\\data\\lifecycle\\exec_roster.json\"
"'$manifestLineNums = @()
for ($i = 0; $i -lt $lines.Count; $i++) {
    if ($lines[$i] -match '"'\"manifest_id\"') {
        "'$manifestLineNums += $i
    }
}
Write-Output "Total manifest_id lines: $($manifestLineNums.Count)"
# Show distinct manifest IDs
$manifestIds = $lines | Select-String '"'\"manifest_id\":\\s*\"(["'^"]+)"'"' | ForEach-Object { "'$_.Matches[0].Groups[1].Value } | Sort-Object -Unique
Write-Output "Distinct manifest IDs in roster:"
$manifestIds | ForEach-Object { Write-Output "  $_" }'

