"C:\\WINDOWS\\System32\\WindowsPowerShell\\v1.0\\powershell.exe" -Command '# For each manifest, count jobs by state
$lines = Get-Content "E:'"\\codex-LOOP\\codex-loop-s-f2\\data\\lifecycle\\exec_roster.json\"
"'$manifests = @{}

# Find all jobs by looking at top-level packet_id entries
for ($i = 0; $i -lt $lines.Count; $i++) {
    if ($lines[$i] -match '"'"'^'"\\s+\"(parent-|adhoc-)[a-f0-9]+["'^"]*":'"\\s*\\{') {
        "'$packetId = [regex]::Match($lines[$i], '"'\"(["'^"]+)":'"\\s*\\{').Groups[1].Value
        # Scan ahead for manifest_id and top-level state
        "'$manifestId = $null
        $topState = $null
        for ($j = $i+1; $j -lt [Math]::Min($i+200, $lines.Count); $j++) {
            if ($lines[$j] -match '"'"'^'"\\s+\"manifest_id\":\\s*\"(["'^"]+)"'"') {
                "'$manifestId = $matches[1]
            }
            # Top-level state is at same indent level as packet_id (6 spaces)
            if ($lines[$j] -match '"'"'^      "state":'"\\s*\"(["'^"]+)"'"') {
                "'$topState = $matches[1]
                break
            }
        }
        if ($manifestId) {
            if (-not $manifests.ContainsKey($manifestId)) {
                $manifests[$manifestId] = @{}
            }
            $state = if ($topState) { $topState } else { "unknown" }
            if (-not $manifests[$manifestId].ContainsKey($state)) { $manifests[$manifestId][$state] = 0 }
            $manifests[$manifestId][$state]++
        }
    }
}

foreach ($mid in $manifests.Keys | Sort-Object) {
    Write-Output "Manifest: $mid"
    foreach ($state in $manifests[$mid].Keys | Sort-Object) {
        Write-Output "  $state : $($manifests[$mid][$state])"
    }
}'

